const excluded=new Set(["69cbfe1f6dbaa9badb0c6b13", "6a565aede592c037e10a3c16", "6a845cd5a5d91e080c06b6e1", "6a845cfd8d1432eeb8016ab9", "6a845d4013c5fb027c0768b2", "6a845ded7d4cbd3ee50a191f", "6a845e4ea5d91e080c06b6ed"]);
const patterns=["!!! DO NOT USE !!!", "!!! DON'T USE !!!", "NOT FOR USE", "DEBUG ITEM", "TEST ITEM", "PLACEHOLDER", "DEV_ONLY", "(DRAFT)"];
export function ruText(value){if(typeof value!=='string')return value??'';if(phrases[value])return phrases[value];if(/^[a-f0-9]{24}(?: (?:Name|Description|ShortName))?$/.test(value))return 'Описание пока не опубликовано';return value.split(' · ').map(part=>phrases[part]||part).join(' · ').replace(/\bPvP\b/g,'PVP').replace(/\bPvE\b/g,'PVE');}
export const currencyLabel=value=>({RUB:'₽',USD:'$',EUR:'€'}[value]||ruText(value));
export const isVisibleItem=item=>!excluded.has(item.id)&&!patterns.some(p=>(item.name||'').toUpperCase().includes(p));
const fields=new Set(['name','shortName','description','label','title','caption','targetNames','text','exitName','skill','customizationTypeName']);
export function localizeDisplay(value,key=''){if(Array.isArray(value))return value.map(x=>localizeDisplay(x,key));if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,localizeDisplay(v,k)]));return fields.has(key)?ruText(value):value;}
